 viewport.addEventListener('pointerdown',event=>{if(event.button!==0||event.target.closest('.node-inline-input,[data-node-edit]'))return;const port=event.target.closest('[data-port]');if(port&&options.canConnect){portDrag={source:port.closest('[data-node-id]').dataset.nodeId,pointer:event.pointerId,x:event.clientX,y:event.clientY,moved:false};viewport.setPointerCapture(event.pointerId);return;}if(event.target.closest('[data-edge-id]'))return;const element=event.target.closest('[data-node-id]');if(element&&linking)return;drag={pointer:event.pointerId,startX:event.clientX,startY:event.clientY,cameraX:session.x,cameraY:session.y,element,node:element?byId.get(element.dataset.nodeId):null,moved:false};if(drag.node){drag.x=drag.node.x;drag.y=drag.node.y;}});
